package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaCelltypeInputsTest {
    @TempDir Path temp;
    private List<FumaCelltypeInputs.Dataset> datasets(boolean missing)throws Exception {return FumaCelltypeInputs.datasets(temp.resolve("datasets.tsv"),new LinkedHashMap<>(),FumaCelltypeTestData.limits(),missing,()->{});}
    @Test void sealedBundleAndEveryResourceIdentityAreChecked()throws Exception {var o=FumaCelltypeTestData.options(temp);var hashes=new LinkedHashMap<Path,String>();var b=FumaCelltypeInputs.bundle(Path.of(o.get("gene-bundle")),"fixture-build",hashes,FumaCelltypeTestData.limits());assertEquals(List.of("E1","E2","E3"),b.genes());assertEquals(3,hashes.size());var d=FumaCelltypeInputs.datasets(temp.resolve("datasets.tsv"),hashes,FumaCelltypeTestData.limits(),false,()->{});assertEquals("fixture-resource",d.get(0).resourceId());assertEquals(List.of("CellA"),d.get(0).cells());assertEquals(5,hashes.size());}
    @Test void changedBundleAndDeclaredBuildCannotBeAdmitted()throws Exception {var o=FumaCelltypeTestData.options(temp);Path b=Path.of(o.get("gene-bundle"));assertThrows(Exception.class,()->FumaCelltypeInputs.bundle(b,"wrong-build",new LinkedHashMap<>(),FumaCelltypeTestData.limits()));Files.writeString(b.resolve("genes.raw"),"changed");assertThrows(Exception.class,()->FumaCelltypeInputs.bundle(b,"fixture-build",new LinkedHashMap<>(),FumaCelltypeTestData.limits()));}
    @Test void exactAverageUniqueGenesAndColumnsAreRequired()throws Exception {FumaCelltypeTestData.options(temp);for(String text:List.of("GENE\tCellA\tMean\nE1\t1\t2\n","GENE\tCellA\tCellA\tAverage\nE1\t1\t2\t3\n","GENE\tCellA\tAverage\nE1\t1\t2\nE1\t3\t4\n")){Files.writeString(temp.resolve("properties.tsv"),text);assertThrows(Exception.class,()->datasets(false));}}
    @Test void missingValuesRequirePolicyAndKeepExactTokens()throws Exception {FumaCelltypeTestData.options(temp);Files.writeString(temp.resolve("properties.tsv"),"GENE\tCellA\tAverage\nE1\tNA\t.1\nE2\t1e-10\tNA\n");assertThrows(Exception.class,()->datasets(false));var d=datasets(true).get(0);assertEquals(List.of("NA",".1"),d.rows().get(0).values());assertEquals(List.of("1e-10","NA"),d.rows().get(1).values());}
    @Test void finiteDecimalGrammarRejectsSpecialAndNonDecimalValues()throws Exception {FumaCelltypeTestData.options(temp);for(String value:List.of("NaN","Inf","1e999","0x1.0p1","")){Files.writeString(temp.resolve("properties.tsv"),"GENE\tCellA\tAverage\nE1\t"+value+"\t.1\n");assertThrows(Exception.class,()->datasets(true));}}
    @Test void completeCoverageIncludesMissingAndExtraGenes()throws Exception {FumaCelltypeTestData.options(temp);Files.writeString(temp.resolve("properties.tsv"),"GENE\tCellA\tAverage\nE1\t1\t.1\nE4\t2\t.2\n");var warnings=new ArrayList<String>();assertThrows(Exception.class,()->FumaCelltypeInputs.coverage(datasets(false),List.of("E1","E2","E3"),false,temp.resolve("error.tsv"),warnings,100,()->{}));assertEquals(4,FumaCelltypeInputs.coverage(datasets(false),List.of("E1","E2","E3"),true,temp.resolve("source.tsv"),warnings,100,()->{}));String text=Files.readString(temp.resolve("source.tsv"));assertTrue(text.contains("outside-gene-analysis-source-ignore"));assertTrue(text.contains("missing-resource-gene-source-default"));assertTrue(warnings.get(0).contains("Required action"));}
    @Test void joinsRetainLeftOrderAndOnlyDropMissingRightAverage()throws Exception {var a=new FumaCelltypeInputs.Dataset("A","a",temp,List.of("CellA","Average"),List.of(new FumaCelltypeInputs.Row("E3",List.of("3","NA")),new FumaCelltypeInputs.Row("E1",List.of("1",".1")),new FumaCelltypeInputs.Row("E2",List.of("2",".2"))));var b=new FumaCelltypeInputs.Dataset("B","b",temp,List.of("CellB","Average"),List.of(new FumaCelltypeInputs.Row("E1",List.of("NA",".5")),new FumaCelltypeInputs.Row("E3",List.of("6",".6")),new FumaCelltypeInputs.Row("E2",List.of("4","NA")),new FumaCelltypeInputs.Row("E4",List.of("9",".9"))));var joined=FumaCelltypeInputs.join(a,List.of("CellA"),b,List.of("CellB"),()->{});assertEquals(List.of("E3","E1"),joined.rows().stream().map(FumaCelltypeInputs.Row::gene).toList());assertEquals(List.of("A:CellA","Average1","B:CellB","Average2"),joined.columns());assertEquals(List.of("3","NA","6",".6"),joined.rows().get(0).values());assertTrue(joined.disposition().stream().anyMatch(r->r[3].equals("excluded-missing-right-Average")));assertTrue(joined.disposition().stream().anyMatch(r->r[3].equals("excluded-right-only-gene")));}
    @Test void joinSerializationUsesFifteenSignificantDigitsWithoutImputation()throws Exception {var joined=new FumaCelltypeInputs.Joined(List.of("A:CellA","Average1"),List.of(new FumaCelltypeInputs.Row("E1",List.of("3.7431058336654923","NA"))),List.of());FumaCelltypeInputs.writeJoined(temp.resolve("joined.tsv"),joined);String row=Files.readAllLines(temp.resolve("joined.tsv")).get(1);assertEquals("E1\t3.74310583366549\tNA",row);}
    @Test void limitsCoverCompleteInputsAndCoverageLedgers()throws Exception {FumaCelltypeTestData.options(temp);assertThrows(Exception.class,()->FumaCelltypeInputs.datasets(temp.resolve("datasets.tsv"),new LinkedHashMap<>(),new FumaCelltypeInputs.Limits(100000,100,10,100,5),false,()->{}));assertThrows(Exception.class,()->FumaCelltypeInputs.coverage(datasets(false),List.of("E1","E2","E3"),true,temp.resolve("limited.tsv"),new ArrayList<>(),2,()->{}));}
    @Test void manifestsResolveUnicodePathsAndRejectRepeatedDatasetIds()throws Exception {FumaCelltypeTestData.options(temp);Path unicode=temp.resolve("resources Ω");Files.createDirectory(unicode);Files.copy(temp.resolve("properties.tsv"),unicode.resolve("x.tsv"));Files.writeString(temp.resolve("datasets.tsv"),"dataset\tresource_id\tpath\nDataA\tfixture µ\tresources Ω/x.tsv\n");assertEquals(unicode.resolve("x.tsv"),datasets(false).get(0).source());Files.writeString(temp.resolve("datasets.tsv"),Files.readString(temp.resolve("datasets.tsv"))+"DataA\tduplicate\tproperties.tsv\n");assertThrows(Exception.class,()->datasets(false));}
    @Test void callbacksAndSourceIntegrityChecksAreActive()throws Exception {FumaCelltypeTestData.options(temp);assertThrows(IllegalStateException.class,()->FumaCelltypeInputs.datasets(temp.resolve("datasets.tsv"),new LinkedHashMap<>(),FumaCelltypeTestData.limits(),false,()->{throw new IllegalStateException("cancel");}));var hashes=new LinkedHashMap<Path,String>();FumaCelltypeInputs.raw(temp.resolve("properties.tsv"),hashes,10000);Files.writeString(temp.resolve("properties.tsv"),"changed");assertThrows(Exception.class,()->FumaCelltypeInputs.verify(hashes));}
    @Test void unknownJoinCellsAndEmptyIntersectionsFail()throws Exception {var a=new FumaCelltypeInputs.Dataset("A","a",temp,List.of("CellA","Average"),List.of(new FumaCelltypeInputs.Row("E1",List.of("1","1"))));var b=new FumaCelltypeInputs.Dataset("B","b",temp,List.of("CellB","Average"),List.of(new FumaCelltypeInputs.Row("E2",List.of("2","2"))));assertThrows(Exception.class,()->FumaCelltypeInputs.join(a,List.of("Unknown"),b,List.of("CellB"),()->{}));assertThrows(Exception.class,()->FumaCelltypeInputs.join(a,List.of("CellA"),b,List.of("CellB"),()->{}));}
}
